INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运二年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/jiuwudaishi-084-945-september/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年九月，段落 jiu-wudaishi-205deb4a7860-p002029；已核卷号与传主，电子本及异文待纸本校核。", "id": "ca9d8f31-8192-544a-bc5f-23cbf5942e54"}, {"title": "旧五代史·卷96·王瑜传·父王钦祚官职", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/jiuwudaishi-096-wang-qinzuo/source.txt", "note": "《旧五代史》卷96·王瑜传·父王钦祚官职，段落 jiu-wudaishi-205deb4a7860-p002335；已核卷号与传主，电子本及异文待纸本校核。", "id": "9eed6cd5-cdb1-5a63-ba20-7a12e2d7941e"}, {"title": "资治通鉴·卷285·后晋纪六·开运二年八月至十一月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/tongjian-285-945-august-november/source.txt", "note": "《资治通鉴》卷285·后晋纪六·开运二年八月至十一月及追述，段落 zizhi-tongjian-a63549944a71-p003383；已核卷号与传主，电子本及异文待纸本校核。", "id": "96d6ca1f-263a-53b6-ab58-791ddc7e8727"}, {"title": "新五代史·卷65·南汉世家·刘晟乾和三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-065-hongya-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟乾和三年，段落 xin-wudaishi-b08f244b9241-p003283；已核卷号与传主，电子本及异文待纸本校核。", "id": "6d196b4f-4d62-5838-ad21-786fb0df513d"}, {"title": "新五代史·卷68·闽世家·王氏灭亡纪年说明", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-068-fall-year/source.txt", "note": "《新五代史》卷68·闽世家·王氏灭亡纪年说明，段落 xin-wudaishi-b08f244b9241-p003415；已核卷号与传主，电子本及异文待纸本校核。", "id": "af3458df-4cef-5654-8b54-5a0ab901bec3"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "新五代史·卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理）", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/xinwudaishi-068-li-ren-da/source.txt", "note": "《新五代史》卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理），段落 xin-wudaishi-b08f244b9241-p003414；上下文、卷界及传主已校核，纸本及异文待核。", "id": "4c007e7d-1965-54c8-99ae-fa57eab6e1a4"}, {"title": "旧五代史·卷84·晋少帝本纪·开运二年八月奏马希杲卒", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-084-945-august/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年八月奏马希杲卒，段落 jiu-wudaishi-205deb4a7860-p002028；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "d771a89b-2508-55c3-a20a-5b5c55c4b3b0"}, {"title": "旧五代史·卷109·杜重威传·擅离恒州及此后事", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-109-du-leaves/source.txt", "note": "《旧五代史》卷109·杜重威传·擅离恒州及此后事，段落 jiu-wudaishi-205deb4a7860-p002617；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "186cc6db-af14-5154-813a-ddcc1501d60e"}, {"title": "旧五代史·卷89·冯玉传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7bc781abc574bfda6b3d4fe1b21ccaaaf8a0ef7e/content/books/zizhi-tongjian/vol-283/year-0943/part-04/sources/library/jiuwudaishi-089-feng-yu/source.txt", "note": "《旧五代史》卷89·冯玉传，段落 jiu-wudaishi-205deb4a7860-p002144；已核上下文及传主，纸本及异文待核。", "id": "18569c3f-9e32-58d3-a7d2-ead68bc8f1de"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "董思安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年参与反朱文进的谋议和泉州政变，后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "385e66d6-1650-5db4-a215-4208ca968420"}, {"name": "王建封", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上元人，南唐将领。945年《资治通鉴》记他以先锋桥道使身份率先登上建州城墙，南唐军随后攻破建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "a7b5c6e1-9057-52ff-8317-f82698daacd6"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王忠顺", "aliases": ["王忠順"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年与留从效、董思安、张汉思议反朱文进政权，参与泉州政变后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "5c73751d-6af3-5516-935f-53a4ace23f02"}, {"name": "杨思恭", "aliases": ["楊思恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建阳人，王延政属下的节度巡官。943年王延政建殷后任兵部尚书，不久升仆射、录军国事。史书记他加重田亩山泽及鱼盐蔬果税负，记载当时人称他为杨剥皮。生卒年尚未核。", "biography": null, "status": "draft", "id": "588de476-95b1-534e-af0e-97b68a1f83a0"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘雅", "aliases": ["劉弘雅", "刘洪雅", "劉洪雅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘雅，获封王爵之子。", "biography": null, "status": "draft", "id": "b03cbc36-bab1-5094-9267-00775e6297a1"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "王继勋", "aliases": ["王繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年留从效杀黄绍颇后请他主持泉州军府，王延政随后任他为侍中、泉州刺史。具体亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "3ecb3355-a3dd-5a2f-a0b9-12d6af9a06ab"}, {"name": "王继成", "aliases": ["王繼成"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年程谟杀漳州刺史后立他暂掌漳州。亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "4f09de43-cd4b-56a5-a731-b286597a2338"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "王钦祚", "aliases": ["王欽祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋殿中监。945年暂掌恒州事务，奉命征购军粮，把杜重威在恒州的十余万斛粮食登记上报。杜重威上表指责此事，朝廷召王钦祚回京。《旧五代史》也记他奉命在镇州买粮，并在王瑜传记其父钦祚曾任殿中监。生卒年本段未载。", "biography": null, "status": "draft", "id": "c77acad9-f0e6-5732-ba4f-e4294c1a9589"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

